'use client';

import Link from 'next/link';
import { WalletAddress } from '@/components/wallet-address';
import { FormEvent, useCallback, useEffect, useMemo, useState } from 'react';
import { Activity, AlertCircle, AlertTriangle, ArrowDownLeft, ArrowRight, ArrowUpRight, CheckCircle2, ChevronLeft, ChevronRight, Circle, Clipboard, Copy, ExternalLink, Fingerprint, GitBranch, Loader2, Network, Radio, RefreshCw, Search, ShieldAlert, Sparkles, Users } from 'lucide-react';
import { analyzeWalletTransactions, formatEth, type AnalyzedTransaction, type Counterparty, type TransactionDirection, type WalletAnalysis, type WalletTransaction } from '@/lib/wallet-analysis';
import { authenticatedFetch } from '@/lib/client-api';

type WalletResponse = { address: string; balanceWei: string; balanceEth: string; transactionCount: number; transactions: WalletTransaction[]; dataSource: string; verifiedAt: string; network: string };
type WalletMonitor = { id: string; address: string; network: 'ethereum'; is_active: boolean; last_checked_at: string | null; last_successful_check_at: string | null; last_error: string | null; created_at: string };
type GraphDetail = { address: string; relationship: string; transactionCount: number; observedWei: bigint; firstInteraction: string | null; lastInteraction: string | null };
type Prompt = 'Summarize this wallet activity.' | 'Explain the Money Fingerprint.' | 'What suspicious indicators were observed?' | 'Show the major fund movements.' | 'Which transactions require review?' | 'Explain why this case was flagged.';

const ETHEREUM_ADDRESS_PATTERN = /^0x[a-fA-F0-9]{40}$/;
const PAGE_SIZE = 10;

function isRecord(value: unknown): value is Record<string, unknown> { return typeof value === 'object' && value !== null; }
function isWalletTransaction(value: unknown): value is WalletTransaction {
  return isRecord(value) && typeof value.hash === 'string' && typeof value.from === 'string' && (typeof value.to === 'string' || value.to === null) && (typeof value.timestamp === 'string' || value.timestamp === null) && typeof value.value === 'string' && typeof value.blockNumber === 'string' && (value.status === 'success' || value.status === 'failed' || value.status === 'unknown');
}
function normalizeWalletResponse(payload: unknown): WalletResponse | null {
  if (!isRecord(payload) || typeof payload.address !== 'string' || typeof payload.balanceWei !== 'string' || typeof payload.balanceEth !== 'string' || typeof payload.transactionCount !== 'number' || typeof payload.dataSource !== 'string' || typeof payload.verifiedAt !== 'string' || typeof payload.network !== 'string') return null;
  return { address: payload.address, balanceWei: payload.balanceWei, balanceEth: payload.balanceEth, transactionCount: payload.transactionCount, dataSource: payload.dataSource, verifiedAt: payload.verifiedAt, network: payload.network, transactions: Array.isArray(payload.transactions) ? payload.transactions.filter(isWalletTransaction) : [] };
}
function abbreviate(value: string, start = 8, end = 6) { return value.length > start + end ? `${value.slice(0, start)}...${value.slice(-end)}` : value; }
function formatTimestamp(timestamp: string | null) {
  if (!timestamp) return 'Unavailable';
  const date = new Date(timestamp);
  return Number.isNaN(date.getTime()) ? 'Unavailable' : new Intl.DateTimeFormat('en-US', { dateStyle: 'medium', timeStyle: 'short', timeZone: 'UTC' }).format(date);
}
function formatTransactionValue(value: string) { return /^\d+$/.test(value) ? formatEth(BigInt(value)) : 'Unavailable'; }
function formatFrequency(analysis: WalletAnalysis) {
  const { timestampedTransactionCount, windowMs, transactionsPerDay } = analysis.frequency;
  if (timestampedTransactionCount === 0) return 'Unavailable — no timestamped successful transactions were returned.';
  if (timestampedTransactionCount === 1) return 'One timestamped successful transaction was returned.';
  if (windowMs === 0 || transactionsPerDay === null) return 'Successful transactions share the same observed timestamp.';
  const days = windowMs / 86_400_000;
  return `${transactionsPerDay.toFixed(2)} successful transactions/day across ${days < 1 ? `${Math.max(1, Math.round(days * 24))} hours` : `${days.toFixed(days < 10 ? 1 : 0)} days`}.`;
}
function riskStatus(analysis: WalletAnalysis) { return analysis.risk.level === 'Elevated' || analysis.risk.level === 'Moderate' ? 'Review Required' : analysis.risk.level === 'Low' ? 'Indicators Detected' : 'Not Assessed'; }
function riskBadgeClass(level: WalletAnalysis['risk']['level']) { return level === 'Elevated' ? 'border-red-400/30 bg-red-400/10 text-red-200' : level === 'Moderate' ? 'border-amber-400/30 bg-amber-400/10 text-amber-200' : level === 'Low' ? 'border-yellow-400/30 bg-yellow-400/10 text-yellow-200' : 'border-slate-700 bg-slate-800 text-slate-300'; }
function activityBounds(transactions: WalletTransaction[]) {
  const dated = transactions.filter((transaction) => transaction.timestamp && !Number.isNaN(Date.parse(transaction.timestamp))).sort((left, right) => Date.parse(left.timestamp || '') - Date.parse(right.timestamp || ''));
  return { first: dated[0]?.timestamp || null, latest: dated[dated.length - 1]?.timestamp || null };
}
function directionForTransaction(transaction: WalletTransaction, wallet: string, analyzed: Map<string, AnalyzedTransaction>): TransactionDirection {
  return analyzed.get(transaction.hash)?.direction || (transaction.from.toLowerCase() === wallet.toLowerCase() ? 'outgoing' : transaction.to?.toLowerCase() === wallet.toLowerCase() ? 'incoming' : 'unclassified');
}
function directionLabel(direction: TransactionDirection) { return direction === 'incoming' ? 'Incoming' : direction === 'outgoing' ? 'Outgoing' : direction === 'self' ? 'Self' : 'Unclassified'; }
function getCounterpartyDetail(counterparty: Counterparty, analysis: WalletAnalysis): GraphDetail {
  const lower = counterparty.address.toLowerCase();
  const interactions = [...analysis.incomingTransactions, ...analysis.outgoingTransactions].filter((transaction) => transaction.from.toLowerCase() === lower || transaction.to?.toLowerCase() === lower).sort((left, right) => (left.timestampMs || 0) - (right.timestampMs || 0));
  return { address: counterparty.address, relationship: counterparty.incomingCount > 0 && counterparty.outgoingCount > 0 ? 'Bidirectional counterparty' : counterparty.incomingCount > 0 ? 'Incoming wallet' : 'Outgoing destination', transactionCount: counterparty.incomingCount + counterparty.outgoingCount, observedWei: counterparty.incomingWei + counterparty.outgoingWei, firstInteraction: interactions[0]?.timestamp || null, lastInteraction: interactions[interactions.length - 1]?.timestamp || null };
}
function evidenceReply(prompt: Prompt, analysis: WalletAnalysis | null) {
  if (!analysis || analysis.successfulTransactionCount === 0) return 'Insufficient verified blockchain evidence to determine this.';
  if (prompt === 'Summarize this wallet activity.') return `${analysis.successfulTransactionCount} successful normal Ethereum transactions were observed in the retrieved history: ${analysis.incomingTransactions.length} incoming and ${analysis.outgoingTransactions.length} outgoing. Observed ETH received: ${formatEth(analysis.totalReceivedWei)}; observed ETH sent: ${formatEth(analysis.totalSentWei)}.`;
  if (prompt === 'Explain the Money Fingerprint.') return `The Money Fingerprint summarizes observed behavior: ${analysis.counterparties.length} unique counterparties, ${formatFrequency(analysis)}, and a largest observed transfer of ${analysis.largestTransaction ? formatEth(analysis.largestTransaction.valueWei) : 'Unavailable'}. It does not by itself establish fraud.`;
  if (prompt === 'What suspicious indicators were observed?' || prompt === 'Explain why this case was flagged.') return analysis.risk.signals.length > 0 ? `Observed risk indicators: ${analysis.risk.signals.join(' ')} These are behavioral indicators, not a finding of criminal activity.` : 'Insufficient verified blockchain evidence to determine this.';
  if (prompt === 'Show the major fund movements.') return analysis.largestTransaction ? `The largest observed successful transfer was ${formatEth(analysis.largestTransaction.valueWei)} (${directionLabel(analysis.largestTransaction.direction).toLowerCase()}) at ${formatTimestamp(analysis.largestTransaction.timestamp)} UTC. This is limited to retrieved normal Ethereum transactions.` : 'Insufficient verified blockchain evidence to determine this.';
  return analysis.splittingAlarm ? `${analysis.splittingAlarm.transactionCount} outgoing transfers to ${analysis.splittingAlarm.destinationCount} destinations within 24 hours meet the configured distribution review rule. Review the listed transactions and context; the rule does not establish fraud.` : 'No individual transaction is automatically designated for review by the retrieved evidence. Review the Risk Analysis and any observed outbound pattern in context.';
}

export default function Investigate() {
  const [address, setAddress] = useState('');
  const [result, setResult] = useState<WalletResponse | null>(null);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [monitor, setMonitor] = useState<WalletMonitor | null>(null);
  const [monitorLoading, setMonitorLoading] = useState(false);
  const [monitorError, setMonitorError] = useState('');
  const [monitorMessage, setMonitorMessage] = useState('');
  const [selectedNode, setSelectedNode] = useState<GraphDetail | null>(null);
  const [query, setQuery] = useState('');
  const [directionFilter, setDirectionFilter] = useState<'all' | TransactionDirection>('all');
  const [statusFilter, setStatusFilter] = useState<'all' | WalletTransaction['status']>('all');
  const [sortBy, setSortBy] = useState<'newest' | 'oldest' | 'value-high' | 'value-low'>('newest');
  const [page, setPage] = useState(1);
  const [copied, setCopied] = useState('');
  const [assistantAnswer, setAssistantAnswer] = useState('Select a prompt to summarize the verified evidence from this analysis.');

  const transactions = result?.transactions ?? [];
  const analysis = useMemo(() => result ? analyzeWalletTransactions(result.address, transactions) : null, [result, transactions]);
  const analysisByHash = useMemo(() => new Map((analysis ? [...analysis.incomingTransactions, ...analysis.outgoingTransactions] : []).map((transaction) => [transaction.hash, transaction])), [analysis]);
  const bounds = useMemo(() => activityBounds(transactions), [transactions]);
  const graphNodes = useMemo(() => analysis ? analysis.counterparties.slice(0, 6).map((counterparty) => getCounterpartyDetail(counterparty, analysis)) : [], [analysis]);
  const filteredTransactions = useMemo(() => {
    const normalizedQuery = query.trim().toLowerCase();
    const rows = transactions.filter((transaction) => {
      const direction = result ? directionForTransaction(transaction, result.address, analysisByHash) : 'unclassified';
      return (directionFilter === 'all' || direction === directionFilter) && (statusFilter === 'all' || transaction.status === statusFilter) && (!normalizedQuery || [transaction.hash, transaction.from, transaction.to || '', transaction.blockNumber].some((value) => value.toLowerCase().includes(normalizedQuery)));
    });
    return rows.sort((left, right) => {
      if (sortBy === 'value-high') return BigInt(right.value) > BigInt(left.value) ? 1 : BigInt(right.value) < BigInt(left.value) ? -1 : 0;
      if (sortBy === 'value-low') return BigInt(left.value) > BigInt(right.value) ? 1 : BigInt(left.value) < BigInt(right.value) ? -1 : 0;
      const difference = Date.parse(right.timestamp || '') - Date.parse(left.timestamp || '');
      return sortBy === 'newest' ? difference : -difference;
    });
  }, [analysisByHash, directionFilter, query, result, sortBy, statusFilter, transactions]);
  const totalPages = Math.max(1, Math.ceil(filteredTransactions.length / PAGE_SIZE));
  const visibleTransactions = filteredTransactions.slice((Math.min(page, totalPages) - 1) * PAGE_SIZE, Math.min(page, totalPages) * PAGE_SIZE);
  useEffect(() => setPage(1), [query, directionFilter, statusFilter, sortBy]);
  useEffect(() => {
    const requestedAddress = new URLSearchParams(window.location.search).get('address');
    if (requestedAddress) setAddress(requestedAddress);
  }, []);

  const loadMonitor = useCallback(async (walletAddress: string) => {
    try { const response = await authenticatedFetch(`/api/monitors?address=${encodeURIComponent(walletAddress)}`); const payload = await response.json(); if (!response.ok) throw new Error(typeof payload?.error === 'string' ? payload.error : 'Unable to load monitoring status.'); setMonitor(Array.isArray(payload?.monitors) && payload.monitors.length > 0 ? payload.monitors[0] as WalletMonitor : null); }
    catch (loadError) { setMonitorError(loadError instanceof Error ? loadError.message : 'Unable to load monitoring status.'); }
  }, []);
  useEffect(() => { if (!result) { setMonitor(null); setMonitorError(''); setMonitorMessage(''); return; } void loadMonitor(result.address); const refresh = window.setInterval(() => void loadMonitor(result.address), 60_000); return () => window.clearInterval(refresh); }, [loadMonitor, result]);

  async function investigateWallet(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); const walletAddress = address.trim(); setError(''); setResult(null); setSelectedNode(null); setAssistantAnswer('Select a prompt to summarize the verified evidence from this analysis.');
    if (!ETHEREUM_ADDRESS_PATTERN.test(walletAddress)) { setError('Enter a valid Ethereum wallet address beginning with 0x.'); return; }
    setLoading(true);
    try { const response = await authenticatedFetch(`/api/wallet?address=${encodeURIComponent(walletAddress)}`); const payload = await response.json(); if (!response.ok) throw new Error(typeof payload?.error === 'string' ? payload.error : 'Unable to retrieve this wallet.'); const walletResult = normalizeWalletResponse(payload); if (!walletResult) throw new Error('The wallet service returned an invalid response.'); setResult(walletResult); }
    catch (requestError) { setError(requestError instanceof Error ? requestError.message : 'Unable to retrieve this wallet. Please try again.'); }
    finally { setLoading(false); }
  }
  async function startMonitoring() { if (!result) return; setMonitorLoading(true); setMonitorError(''); setMonitorMessage(''); try { const response = await authenticatedFetch('/api/monitors', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ address: result.address }) }); const payload = await response.json(); if (!response.ok) throw new Error(typeof payload?.error === 'string' ? payload.error : 'Unable to start monitoring.'); setMonitor(payload.monitor as WalletMonitor); setMonitorMessage(payload.created ? 'Monitoring is active. Current Ethereum history was saved as the baseline.' : 'Monitoring is active.'); } catch (requestError) { setMonitorError(requestError instanceof Error ? requestError.message : 'Unable to start monitoring.'); } finally { setMonitorLoading(false); } }
  async function stopMonitoring() { if (!monitor) return; setMonitorLoading(true); setMonitorError(''); setMonitorMessage(''); try { const response = await authenticatedFetch('/api/monitors', { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ monitorId: monitor.id, isActive: false }) }); const payload = await response.json(); if (!response.ok) throw new Error(typeof payload?.error === 'string' ? payload.error : 'Unable to stop monitoring.'); setMonitor(payload.monitor as WalletMonitor); setMonitorMessage('Monitoring is paused. No further Ethereum checks will run for this wallet.'); } catch (requestError) { setMonitorError(requestError instanceof Error ? requestError.message : 'Unable to stop monitoring.'); } finally { setMonitorLoading(false); } }
  async function checkMonitorNow() { if (!monitor) return; setMonitorLoading(true); setMonitorError(''); setMonitorMessage(''); try { const response = await authenticatedFetch('/api/monitors/check', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ monitorId: monitor.id }) }); const payload = await response.json(); if (!response.ok) throw new Error(typeof payload?.error === 'string' ? payload.error : 'Unable to check this wallet.'); const checked = payload.result; setMonitorMessage(`Live check complete: ${checked.newTransactionCount} new transaction${checked.newTransactionCount === 1 ? '' : 's'} and ${checked.newAlertCount} new alert${checked.newAlertCount === 1 ? '' : 's'}.`); await loadMonitor(monitor.address); } catch (requestError) { setMonitorError(requestError instanceof Error ? requestError.message : 'Unable to check this wallet.'); } finally { setMonitorLoading(false); } }
  async function copyValue(value: string) { try { await navigator.clipboard.writeText(value); setCopied(value); window.setTimeout(() => setCopied(''), 1600); } catch { setCopied('Copy unavailable'); } }
  const analysisState = loading ? 'Analyzing' : error ? 'Error' : result ? 'Complete' : 'Ready';

  return <div className="space-y-6 pb-10">
    <header className="page-header"><div><p className="eyebrow">Investigation workspace</p><h1 className="page-title">Wallet Investigation</h1><p className="page-description">Analyze verified blockchain activity, transaction behavior, and direct fund flows.</p></div><DataStatus result={result} loading={loading} error={error} /></header>
    <form id="wallet-investigation" onSubmit={investigateWallet} className="panel-primary p-4 sm:p-5"><div className="grid gap-4 xl:grid-cols-[minmax(0,1fr)_190px_auto] xl:items-end"><div><label htmlFor="wallet-address" className="mb-2 block text-sm font-medium text-slate-200">Ethereum wallet address</label><div className="flex items-center gap-2 rounded-xl border border-slate-700 bg-slate-950 px-3 transition focus-within:border-cyan-400 focus-within:ring-2 focus-within:ring-cyan-400/20"><Search size={18} className="shrink-0 text-cyan-300" /><input id="wallet-address" value={address} onChange={(event) => setAddress(event.target.value)} type="text" autoComplete="off" spellCheck={false} className="min-w-0 flex-1 bg-transparent py-3 font-mono text-sm text-white outline-none placeholder:text-slate-600" placeholder="0x Enter Ethereum wallet address..." aria-describedby="wallet-help" /></div><p id="wallet-help" className="mt-2 text-xs text-slate-500">Analyze recent normal ETH transfers on Ethereum Mainnet. Results include their source, retrieval time, and coverage limits.</p></div><div><span className="mb-2 block text-sm font-medium text-slate-200">Network</span><div className="flex h-[46px] items-center gap-2 rounded-xl border border-slate-700 bg-slate-950 px-3 text-sm text-slate-200"><Circle size={9} className="fill-cyan-300 text-cyan-300" />Ethereum Mainnet</div></div><button type="submit" disabled={loading} className="button-primary h-[46px] px-5">{loading ? <Loader2 size={18} className="animate-spin" /> : <Search size={18} />}{loading ? 'Analyzing wallet' : 'Analyze wallet'}</button></div><div className="mt-4 flex flex-wrap items-center gap-3 text-xs"><span className="text-slate-500">Analysis status</span><span className={`rounded-full border px-2.5 py-1 font-medium ${analysisState === 'Complete' ? 'border-emerald-400/30 bg-emerald-400/10 text-emerald-200' : analysisState === 'Error' ? 'border-red-400/30 bg-red-400/10 text-red-200' : analysisState === 'Analyzing' ? 'border-cyan-400/30 bg-cyan-400/10 text-cyan-200' : 'border-slate-700 bg-slate-800 text-slate-300'}`}>{analysisState}</span></div>{error && <div role="alert" className="mt-4 flex gap-2 rounded-xl border border-red-400/20 bg-red-400/10 p-3 text-sm text-red-200"><AlertCircle size={18} className="shrink-0" /><span>{error}</span></div>}</form>
    <p role="status" className="text-xs text-slate-400">{copied === 'Copy unavailable' ? 'Clipboard unavailable. Open the address or transaction in Etherscan to copy it.' : copied ? 'Copied to clipboard.' : ''}</p>{loading && <LoadingWorkspace />}
    {!loading && !result && !error && <EmptyWorkspace />}
    {result && analysis && <>
      <div className="panel flex flex-wrap items-center justify-between gap-3 p-4"><div><p className="meta-label mb-2">Investigated wallet</p><WalletAddress address={result.address} /></div><nav aria-label="Wallet analysis sections" className="flex flex-wrap gap-2">{[['fund-flow', 'Fund flow'], ['money-fingerprint', 'Fingerprint'], ['risk-signals', 'Risk assessment'], ['fund-splitting', 'Splitting alarm'], ['monitoring', 'Monitoring'], ['transactions', 'Transactions']].map(([id, label]) => <a key={id} href={`#${id}`} className="section-link">{label}</a>)}</nav></div>
      <section className="rounded-xl border border-cyan-400/15 bg-cyan-400/[0.04] px-4 py-3 text-sm text-cyan-100">Scope: retrieved normal Ethereum transactions (up to 50). Token transfers, internal transfers, labels, ownership, and off-chain activity are not included.</section>
      <section><SectionHeading icon={<Activity size={18} />} eyebrow="Verified wallet data" title="Wallet Overview" description="Facts returned by the server-side Ethereum data lookup." /><div className="mt-4 grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><OverviewMetric label="Wallet balance" value={formatTransactionValue(result.balanceWei)} detail="ETH" /><OverviewMetric label="Transaction count" value={String(result.transactionCount)} detail="Network nonce" /><OverviewMetric label="First activity" value={formatTimestamp(bounds.first)} detail="Retrieved history" compact /><OverviewMetric label="Latest activity" value={formatTimestamp(bounds.latest)} detail="Retrieved history" compact /><OverviewMetric label="Risk status" value={riskStatus(analysis)} detail="Behavioral analysis" tone={riskStatus(analysis) === 'Review Required' ? 'amber' : 'cyan'} compact /><OverviewMetric label="Data source" value={result.dataSource} detail={result.network} tone="cyan" /><OverviewMetric label="Verified at" value={formatTimestamp(result.verifiedAt)} detail="UTC" compact /><OverviewMetric label="Retrieved transfers" value={String(analysis.transactionCount)} detail={`${analysis.successfulTransactionCount} successful on-chain`} /></div></section>
      <section id="monitoring" className="rounded-2xl border border-violet-400/20 bg-gradient-to-br from-violet-400/[0.08] to-slate-900/40 p-5 sm:p-6"><div className="flex flex-col gap-4 md:flex-row md:items-start md:justify-between"><div><div className="flex items-center gap-2"><Radio size={19} className={monitor?.is_active ? 'text-emerald-300' : 'text-violet-300'} /><h2 className="text-base font-semibold text-white">Wallet Monitoring</h2></div><p className="mt-2 max-w-2xl text-sm text-slate-400">{!monitor ? 'Save this wallet for periodic server-side Ethereum checks. Existing history becomes the baseline.' : monitor.is_active ? 'Monitoring is active. New alerts apply to activity detected after the baseline.' : 'Monitoring is paused. Periodic Ethereum checks are disabled.'}</p><p className="mt-2 text-xs text-slate-500">Last checked: {formatTimestamp(monitor?.last_checked_at || null)} UTC{monitor?.last_successful_check_at ? ` · last successful: ${formatTimestamp(monitor.last_successful_check_at)} UTC` : ''}</p>{monitor?.last_error && <p className="mt-2 text-xs text-red-300">Last check issue: {monitor.last_error}</p>}{monitorError && <p role="alert" className="mt-2 text-sm text-red-300">{monitorError}</p>}{monitorMessage && <p role="status" className="mt-2 text-sm text-cyan-200">{monitorMessage}</p>}</div><div className="flex shrink-0 flex-wrap gap-2">{!monitor || !monitor.is_active ? <button type="button" onClick={() => void startMonitoring()} disabled={monitorLoading} className="inline-flex items-center gap-2 rounded-lg bg-violet-500 px-4 py-2 text-sm font-medium text-white hover:bg-violet-400 disabled:opacity-60">{monitorLoading ? <Loader2 size={16} className="animate-spin" /> : <Radio size={16} />}{monitor ? 'Resume monitoring' : 'Monitor wallet'}</button> : <><button type="button" onClick={() => void checkMonitorNow()} disabled={monitorLoading} className="inline-flex items-center gap-2 rounded-lg border border-cyan-400/30 px-4 py-2 text-sm font-medium text-cyan-100 hover:bg-cyan-400/10 disabled:opacity-60">{monitorLoading ? <Loader2 size={16} className="animate-spin" /> : <RefreshCw size={16} />}Check now</button><button type="button" onClick={() => void stopMonitoring()} disabled={monitorLoading} className="rounded-lg border border-slate-700 px-4 py-2 text-sm text-slate-300 hover:bg-slate-800 disabled:opacity-60">Pause</button></>}</div></div></section>
      <div className="grid gap-6 2xl:grid-cols-[minmax(0,1.55fr)_minmax(360px,0.85fr)]"><section id="money-fingerprint" className="rounded-2xl border border-slate-800 bg-slate-900/40 p-5 sm:p-6"><SectionHeading icon={<Fingerprint size={18} />} eyebrow="How did the money behave?" title="Money Fingerprint" description="Observable behavior from successful normal Ethereum transfers." /><div className="mt-5 grid gap-3 sm:grid-cols-2 lg:grid-cols-3"><EvidenceMetric label="Incoming funds" value={formatEth(analysis.totalReceivedWei)} detail={`${analysis.incomingTransactions.length} observed transfers`} tone="emerald" /><EvidenceMetric label="Outgoing funds" value={formatEth(analysis.totalSentWei)} detail={`${analysis.outgoingTransactions.length} observed transfers`} tone="violet" /><EvidenceMetric label="Transfer frequency" value={analysis.frequency.transactionsPerDay === null ? 'Unavailable' : `${analysis.frequency.transactionsPerDay.toFixed(2)}/day`} detail={formatFrequency(analysis)} /><EvidenceMetric label="Unique counterparties" value={String(analysis.counterparties.length)} detail="Successful transfer counterparties" /><EvidenceMetric label="Average transfer value" value={formatEth(analysis.averageTransactionWei)} detail="Successful transfer average" /><EvidenceMetric label="Largest transfer" value={analysis.largestTransaction ? formatEth(analysis.largestTransaction.valueWei) : 'Unavailable'} detail={analysis.largestTransaction ? `${directionLabel(analysis.largestTransaction.direction)} · ${formatTimestamp(analysis.largestTransaction.timestamp)}` : 'No successful transfer'} /></div><div className="mt-5 rounded-xl border border-slate-800 bg-slate-950/50 p-4"><div className="flex items-center justify-between gap-4"><p className="text-xs font-medium uppercase tracking-wide text-slate-400">Observed flow balance</p><p className="font-mono text-sm text-slate-200">Net {formatEth(analysis.netFlowWei)}</p></div><FlowBar incoming={analysis.totalReceivedWei} outgoing={analysis.totalSentWei} /></div><p className="mt-4 text-xs leading-5 text-slate-500">Money Fingerprint summarizes observable transaction behavior. It does not by itself establish fraud.</p></section><section id="risk-signals" className="rounded-2xl border border-slate-800 bg-slate-900/40 p-5 sm:p-6"><SectionHeading icon={<ShieldAlert size={18} />} eyebrow="Explainable, evidence-bound" title="Risk Assessment" description="This is a transparent behavioral screen, not an attribution or criminal finding." /><div className="mt-5 space-y-2"><IndicatorRow label="Transaction velocity" state={analysis.frequency.transactionsPerDay === null ? 'Insufficient data' : analysis.frequency.transactionsPerDay >= 20 && analysis.successfulTransactionCount >= 10 ? 'Observed' : 'Not observed'} detail={formatFrequency(analysis)} /><IndicatorRow label="Fund fragmentation" state={analysis.splittingAlarm ? 'Observed' : analysis.outgoingTransactions.length < 3 ? 'Insufficient data' : 'Not observed'} detail={analysis.splittingAlarm ? `${analysis.splittingAlarm.destinationCount} destinations within 24 hours` : 'Configured 3-destination, 24-hour rule'} /><IndicatorRow label="Counterparty concentration" state={analysis.successfulTransactionCount === 0 ? 'Insufficient data' : analysis.counterparties.length > 0 && (analysis.counterparties[0].incomingCount + analysis.counterparties[0].outgoingCount) / analysis.successfulTransactionCount >= 0.6 ? 'Observed' : 'Not observed'} detail={analysis.counterparties[0] ? `${analysis.counterparties[0].incomingCount + analysis.counterparties[0].outgoingCount} interactions with most active counterparty` : 'No counterparties'} /><IndicatorRow label="Repeated destinations" state={analysis.outgoingTransactions.length === 0 ? 'Insufficient data' : analysis.counterparties.some((counterparty) => counterparty.outgoingCount >= 2) ? 'Observed' : 'Not observed'} detail="Repeated recipient interactions in retrieved history" /><IndicatorRow label="Rapid movement" state={analysis.frequency.transactionsPerDay === null ? 'Insufficient data' : analysis.frequency.transactionsPerDay >= 20 ? 'Observed' : 'Not observed'} detail="Based on observed successful transfer frequency" /><IndicatorRow label="Multi-hop movement" state="Insufficient data" detail="The current retrieval does not trace beyond direct counterparties" /></div><div className="mt-5 rounded-xl border border-cyan-400/15 bg-cyan-400/[0.05] p-4"><div className="flex items-center justify-between gap-3"><span className={`rounded-full border px-2.5 py-1 text-xs font-medium ${riskBadgeClass(analysis.risk.level)}`}>{analysis.risk.level}</span><span className="font-mono text-sm text-slate-200">{analysis.risk.score === null ? 'Risk Score: Unavailable' : `Risk Score: ${analysis.risk.score}/100`}</span></div><p className="mt-3 text-xs leading-5 text-slate-400">Score inputs: short-window distribution, recipient diversity, observed frequency, and failed-transaction ratio. {analysis.risk.signals.join(' ')}</p></div></section></div>
      <div className="grid gap-6 xl:grid-cols-2"><section id="fund-splitting" className="rounded-2xl border border-amber-400/20 bg-amber-400/[0.035] p-5 sm:p-6"><SectionHeading icon={<AlertTriangle size={18} />} eyebrow="Did the money suddenly fragment?" title="Fund Splitting Alarm" description="A review signal, never a fraud determination." />{analysis.splittingAlarm ? <div className="mt-5 space-y-4"><div className="inline-flex items-center gap-2 rounded-full border border-amber-400/30 bg-amber-400/10 px-3 py-1 text-xs font-medium text-amber-100"><AlertTriangle size={14} />INDICATOR DETECTED</div><EvidenceGrid items={[["Evidence", `${analysis.splittingAlarm.transactionCount} outgoing transfers to ${analysis.splittingAlarm.destinationCount} destinations`], ["Observation", `${formatEth(analysis.splittingAlarm.totalWei)} observed in a 24-hour window`], ["Time interval", `${formatTimestamp(analysis.splittingAlarm.start)} to ${formatTimestamp(analysis.splittingAlarm.end)} UTC`], ["Interpretation", 'The distribution pattern may warrant further investigation.']]} /></div> : <div className="mt-5"><div className="inline-flex rounded-full border border-slate-700 bg-slate-800 px-3 py-1 text-xs font-medium text-slate-300">{analysis.outgoingTransactions.length < 3 ? 'REVIEW REQUIRED' : 'NO INDICATOR'}</div><p className="mt-4 rounded-xl border border-dashed border-slate-700 bg-slate-950/35 p-4 text-sm text-slate-400">{analysis.outgoingTransactions.length < 3 ? 'Insufficient successful outgoing transfers to evaluate the configured splitting rule.' : 'No observed pattern met the configured rule of sending ETH to 3 or more distinct recipient addresses within 24 hours.'}</p></div>}<p className="mt-5 text-xs leading-5 text-slate-500">Addresses may be externally owned wallets or smart contracts. Ownership and intent are unknown.</p></section><section className="rounded-2xl border border-violet-400/20 bg-violet-400/[0.035] p-5 sm:p-6"><SectionHeading icon={<GitBranch size={18} />} eyebrow="Compare observed relationships" title="Cross-Wallet Investigation" description="Connection findings must be supported by shared case evidence." /><div className="mt-5 rounded-xl border border-dashed border-violet-400/20 bg-slate-950/35 p-5"><p className="text-sm font-medium text-slate-200">Insufficient verified blockchain evidence to determine a connection.</p><p className="mt-2 text-sm leading-6 text-slate-400">This wallet-only view does not associate the address with multiple private cases or infer shared ownership. Use Cases to compare authorized case records and see transaction-level evidence when it exists.</p><Link href="/cases" className="button-secondary mt-4">Compare case evidence<ArrowRight size={15} /></Link></div><div className="mt-4 grid gap-2 sm:grid-cols-2"><EvidenceMetric label="Shared wallet" value="Unknown" detail="Requires case association" /><EvidenceMetric label="Shared transaction path" value="Unknown" detail="Requires cross-case analysis" /></div></section></div>
      <section id="fund-flow" className="rounded-2xl border border-slate-800 bg-slate-900/40 p-5 sm:p-6"><SectionHeading icon={<Network size={18} />} eyebrow="Direct counterparties only" title="Fund Flow" description="Click an observed node to inspect the direct relationship. No ownership is asserted." />{graphNodes.length === 0 ? <NoData message="Blockchain graph unavailable for this analysis." /> : <div className="mt-5 grid gap-5 lg:grid-cols-[minmax(0,1fr)_320px]"><div className="overflow-hidden rounded-xl border border-slate-800 bg-slate-950/55 p-4"><div className="flex flex-col items-stretch gap-3 md:flex-row md:items-center md:justify-center"><div className="flex flex-1 flex-col gap-2">{graphNodes.filter((node) => node.relationship !== 'Outgoing destination').slice(0, 3).map((node) => <GraphNode key={node.address} detail={node} onSelect={setSelectedNode} selected={selectedNode?.address === node.address} />)}</div><div className="flex shrink-0 items-center justify-center gap-1 text-cyan-300"><ArrowRight size={18} /><span className="text-[10px] uppercase tracking-wide">Flow</span><ArrowRight size={18} /></div><button type="button" onClick={() => setSelectedNode({ address: result.address, relationship: 'Investigated wallet', transactionCount: analysis.successfulTransactionCount, observedWei: analysis.totalReceivedWei + analysis.totalSentWei, firstInteraction: bounds.first, lastInteraction: bounds.latest })} className={`rounded-xl border p-4 text-left transition ${selectedNode?.address === result.address ? 'border-cyan-300 bg-cyan-400/15 ring-1 ring-cyan-300/40' : 'border-cyan-400/30 bg-cyan-400/10 hover:bg-cyan-400/15'}`}><p className="text-[10px] font-medium uppercase tracking-[0.18em] text-cyan-200">Investigated wallet</p><p className="mt-2 font-mono text-sm text-white">{abbreviate(result.address)}</p><p className="mt-2 text-xs text-cyan-100">{analysis.successfulTransactionCount} successful transfers</p></button><div className="flex shrink-0 items-center justify-center gap-1 text-violet-300"><ArrowRight size={18} /><span className="text-[10px] uppercase tracking-wide">Flow</span><ArrowRight size={18} /></div><div className="flex flex-1 flex-col gap-2">{graphNodes.filter((node) => node.relationship !== 'Incoming wallet').slice(0, 3).map((node) => <GraphNode key={node.address} detail={node} onSelect={setSelectedNode} selected={selectedNode?.address === node.address} />)}</div></div></div><GraphDetailPanel detail={selectedNode} /></div>}</section>
      <section className="rounded-2xl border border-slate-800 bg-slate-900/40 p-5 sm:p-6"><SectionHeading icon={<Users size={18} />} eyebrow="Most active direct relationships" title="Counterparties" description="Direct successful normal ETH transfer counterparties in the retrieved history." />{analysis.counterparties.length === 0 ? <NoData message="No counterparties were found in the retrieved successful ETH transfers." /> : <div className="mt-5 overflow-x-auto rounded-xl border border-slate-800"><table className="technical-table min-w-[680px]"><thead className="bg-slate-950/70 text-xs uppercase tracking-wide text-slate-500"><tr><th className="px-4 py-3">Counterparty</th><th className="px-4 py-3">Interactions</th><th className="px-4 py-3">ETH received</th><th className="px-4 py-3">ETH sent</th><th className="px-4 py-3">Evidence</th></tr></thead><tbody className="divide-y divide-slate-800">{analysis.counterparties.slice(0, 10).map((counterparty) => <tr key={counterparty.address} className="hover:bg-slate-800/30"><td className="px-4 py-3 font-mono text-cyan-200" title={counterparty.address}><WalletAddress address={counterparty.address} /></td><td className="px-4 py-3 text-slate-300">{counterparty.incomingCount + counterparty.outgoingCount}</td><td className="px-4 py-3 font-mono text-emerald-200">{formatEth(counterparty.incomingWei)}</td><td className="px-4 py-3 font-mono text-violet-200">{formatEth(counterparty.outgoingWei)}</td><td className="px-4 py-3"><button type="button" onClick={() => setSelectedNode(getCounterpartyDetail(counterparty, analysis))} className="text-xs font-medium text-cyan-200 hover:text-cyan-100">Inspect relationship</button></td></tr>)}</tbody></table></div>}</section>
      <section id="transactions" className="rounded-2xl border border-slate-800 bg-slate-900/40 p-5 sm:p-6"><div className="flex flex-col justify-between gap-4 lg:flex-row lg:items-end"><SectionHeading icon={<Clipboard size={18} />} eyebrow="Retrieved transaction evidence" title="Transaction Activity" description="Search, filter, sort, and review the returned normal Ethereum transactions." /><p className="text-xs text-slate-500">{filteredTransactions.length} matching of {transactions.length} retrieved</p></div><div className="mt-5 grid gap-3 md:grid-cols-2 xl:grid-cols-4"><label className="relative"><span className="sr-only">Search transactions</span><Search size={16} className="pointer-events-none absolute left-3 top-3 text-slate-500" /><input value={query} onChange={(event) => setQuery(event.target.value)} className="w-full rounded-lg border border-slate-700 bg-slate-950 py-2.5 pl-9 pr-3 text-sm text-white outline-none focus:border-cyan-400" placeholder="Search hash or address" /></label><select value={directionFilter} onChange={(event) => setDirectionFilter(event.target.value as typeof directionFilter)} aria-label="Filter by direction" className="rounded-lg border border-slate-700 bg-slate-950 px-3 py-2.5 text-sm text-slate-200 outline-none focus:border-cyan-400"><option value="all">All directions</option><option value="incoming">Incoming</option><option value="outgoing">Outgoing</option><option value="self">Self</option><option value="unclassified">Unclassified</option></select><select value={statusFilter} onChange={(event) => setStatusFilter(event.target.value as typeof statusFilter)} aria-label="Filter by status" className="rounded-lg border border-slate-700 bg-slate-950 px-3 py-2.5 text-sm text-slate-200 outline-none focus:border-cyan-400"><option value="all">All statuses</option><option value="success">Success</option><option value="failed">Failed</option><option value="unknown">Unknown</option></select><select value={sortBy} onChange={(event) => setSortBy(event.target.value as typeof sortBy)} aria-label="Sort transactions" className="rounded-lg border border-slate-700 bg-slate-950 px-3 py-2.5 text-sm text-slate-200 outline-none focus:border-cyan-400"><option value="newest">Newest first</option><option value="oldest">Oldest first</option><option value="value-high">Value: high to low</option><option value="value-low">Value: low to high</option></select></div>{transactions.length === 0 ? <div className="mt-5"><NoData message="No normal Ethereum transactions were found for this wallet." /></div> : filteredTransactions.length === 0 ? <div className="mt-5"><NoData message="No transactions match the selected filters." /></div> : <><div className="mt-5 overflow-x-auto rounded-xl border border-slate-800"><table className="technical-table min-w-[1160px]"><thead className="bg-slate-950/70 text-xs uppercase tracking-wide text-slate-500"><tr><th className="px-4 py-3">Status</th><th className="px-4 py-3">Direction</th><th className="px-4 py-3">From</th><th className="px-4 py-3">To</th><th className="px-4 py-3">Value</th><th className="px-4 py-3">Block</th><th className="px-4 py-3">Timestamp</th><th className="px-4 py-3">Transaction hash</th></tr></thead><tbody className="divide-y divide-slate-800">{visibleTransactions.map((transaction) => { const direction = directionForTransaction(transaction, result.address, analysisByHash); return <tr key={transaction.hash} className="hover:bg-slate-800/30"><td className="px-4 py-3"><StatusPill status={transaction.status} /></td><td className="px-4 py-3"><DirectionPill direction={direction} /></td><AddressCell address={transaction.from} copied={copied} onCopy={copyValue} /><AddressCell address={transaction.to} copied={copied} onCopy={copyValue} /><td className="px-4 py-3 font-mono text-slate-100">{formatTransactionValue(transaction.value)}</td><td className="px-4 py-3 font-mono text-slate-400">{transaction.blockNumber || 'Unavailable'}</td><td className="px-4 py-3 whitespace-nowrap text-slate-400">{formatTimestamp(transaction.timestamp)}</td><td className="px-4 py-3"><div className="flex items-center gap-2"><a href={`https://etherscan.io/tx/${transaction.hash}`} target="_blank" rel="noreferrer" className="font-mono text-cyan-200 hover:text-cyan-100" title={transaction.hash}>{abbreviate(transaction.hash)}</a><button type="button" onClick={() => void copyValue(transaction.hash)} aria-label={`Copy transaction hash ${transaction.hash}`} className="text-slate-500 hover:text-cyan-200"><Copy size={14} /></button><a href={`https://etherscan.io/tx/${transaction.hash}`} target="_blank" rel="noreferrer" aria-label={`View transaction ${transaction.hash} on Etherscan`} className="text-slate-500 hover:text-cyan-200"><ExternalLink size={14} /></a></div></td></tr>; })}</tbody></table></div><div className="mt-4 flex items-center justify-between gap-3"><p className="text-xs text-slate-500">Page {Math.min(page, totalPages)} of {totalPages}</p><div className="flex gap-2"><button type="button" onClick={() => setPage((current) => Math.max(1, current - 1))} disabled={page <= 1} className="inline-flex items-center gap-1 rounded-lg border border-slate-700 px-3 py-2 text-xs text-slate-300 hover:bg-slate-800 disabled:opacity-40"><ChevronLeft size={15} />Previous</button><button type="button" onClick={() => setPage((current) => Math.min(totalPages, current + 1))} disabled={page >= totalPages} className="inline-flex items-center gap-1 rounded-lg border border-slate-700 px-3 py-2 text-xs text-slate-300 hover:bg-slate-800 disabled:opacity-40">Next<ChevronRight size={15} /></button></div></div></>}</section>
      <section className="rounded-2xl border border-cyan-400/20 bg-gradient-to-br from-cyan-400/[0.07] to-slate-900/50 p-5 sm:p-6"><SectionHeading icon={<Sparkles size={18} />} eyebrow="Evidence-grounded assistant" title="CHAINTRACE Evidence Assistant" description="Prompt responses are generated only from the verified data currently in this workspace." /><div className="mt-5 grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{(['Summarize this wallet activity.', 'Explain the Money Fingerprint.', 'What suspicious indicators were observed?', 'Show the major fund movements.', 'Which transactions require review?', 'Explain why this case was flagged.'] as Prompt[]).map((prompt) => <button type="button" key={prompt} onClick={() => setAssistantAnswer(evidenceReply(prompt, analysis))} className="rounded-xl border border-cyan-400/15 bg-slate-950/45 p-3 text-left text-sm text-slate-300 transition hover:border-cyan-400/40 hover:bg-cyan-400/[0.06] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cyan-300">{prompt}</button>)}</div><div role="status" className="mt-5 rounded-xl border border-slate-800 bg-slate-950/55 p-4"><p className="text-xs font-medium uppercase tracking-wide text-cyan-300">Evidence response</p><p className="mt-2 text-sm leading-6 text-slate-300">{assistantAnswer}</p><p className="mt-3 text-xs text-slate-500">FACTS are derived from the retrieved dataset. Ownership, exchange identity, intent, and case relationships remain unknown unless independently verified.</p></div></section>
    </>}
  </div>;
}

function DataStatus({ result, loading, error }: { result: WalletResponse | null; loading: boolean; error: string }) { const online = Boolean(result && !error && !loading); return <div className={`flex items-center gap-2 rounded-full border px-3 py-2 text-xs font-medium ${online ? 'border-emerald-400/25 bg-emerald-400/10 text-emerald-200' : loading ? 'border-cyan-400/25 bg-cyan-400/10 text-cyan-100' : 'border-slate-700 bg-slate-900 text-slate-400'}`}><Circle size={9} className={online ? 'fill-emerald-300 text-emerald-300' : loading ? 'fill-cyan-300 text-cyan-300 animate-pulse' : 'text-slate-500'} />{online ? `DATA SOURCE: ${result.dataSource.toUpperCase()} · VERIFIED ${formatTimestamp(result.verifiedAt)} UTC` : loading ? 'SYNCING VERIFIED DATA' : 'DATA SOURCE AWAITS ANALYSIS'}</div>; }
function SectionHeading({ icon, eyebrow, title, description }: { icon: React.ReactNode; eyebrow: string; title: string; description: string }) { return <div><div className="flex items-center gap-2 text-cyan-300">{icon}<p className="text-xs font-medium uppercase tracking-[0.16em]">{eyebrow}</p></div><h2 className="mt-2 text-lg font-semibold text-white">{title}</h2><p className="mt-1 text-sm text-slate-400">{description}</p></div>; }
function OverviewMetric({ label, value, detail, tone = 'slate', compact = false }: { label: string; value: string; detail: string; tone?: 'slate' | 'cyan' | 'amber'; compact?: boolean }) { const valueClass = tone === 'cyan' ? 'text-cyan-200' : tone === 'amber' ? 'text-amber-200' : 'text-white'; return <article className="rounded-xl border border-slate-800 bg-slate-900/60 p-4 transition hover:-translate-y-0.5 hover:border-slate-700"><p className="text-xs font-medium uppercase tracking-wide text-slate-500">{label}</p><p className={`mt-2 break-words font-mono ${compact ? 'text-sm' : 'text-lg'} ${valueClass}`}>{value || 'Unavailable'}</p><p className="mt-2 text-xs text-slate-500">{detail}</p></article>; }
function EvidenceMetric({ label, value, detail, tone = 'slate' }: { label: string; value: string; detail: string; tone?: 'slate' | 'emerald' | 'violet' }) { const valueClass = tone === 'emerald' ? 'text-emerald-200' : tone === 'violet' ? 'text-violet-200' : 'text-slate-100'; return <div className="rounded-xl border border-slate-800 bg-slate-950/35 p-3"><p className="text-xs text-slate-500">{label}</p><p className={`mt-1 break-words font-mono text-sm ${valueClass}`}>{value}</p><p className="mt-1.5 text-xs leading-4 text-slate-500">{detail}</p></div>; }
function FlowBar({ incoming, outgoing }: { incoming: bigint; outgoing: bigint }) { const total = incoming + outgoing; if (total === BigInt(0)) return <p className="mt-3 text-xs text-slate-400">No incoming or outgoing ETH value observed.</p>; const incomingPercent = total > BigInt(0) ? Number((incoming * BigInt(100)) / total) : 0; return <div className="mt-3"><div className="flex h-2 overflow-hidden rounded-full bg-slate-800"><div className="bg-emerald-400/80 transition-all" style={{ width: `${incomingPercent}%` }} aria-label={`${incomingPercent}% observed incoming value`} /><div className="flex-1 bg-violet-400/70" aria-label={`${100 - incomingPercent}% observed outgoing value`} /></div><div className="mt-2 flex justify-between text-xs text-slate-500"><span>Incoming {incomingPercent}%</span><span>Outgoing {100 - incomingPercent}%</span></div></div>; }
function IndicatorRow({ label, state, detail }: { label: string; state: 'Observed' | 'Not observed' | 'Insufficient data'; detail: string }) { const stateClass = state === 'Observed' ? 'border-amber-400/25 bg-amber-400/10 text-amber-100' : state === 'Not observed' ? 'border-emerald-400/25 bg-emerald-400/10 text-emerald-100' : 'border-slate-700 bg-slate-800 text-slate-300'; return <div className="flex flex-col items-start justify-between gap-3 sm:flex-row rounded-xl border border-slate-800 bg-slate-950/35 p-3"><div><p className="text-sm text-slate-200">{label}</p><p className="mt-1 text-xs leading-4 text-slate-500">{detail}</p></div><span className={`shrink-0 rounded-full border px-2 py-1 text-[11px] font-medium ${stateClass}`}>{state}</span></div>; }
function EvidenceGrid({ items }: { items: [string, string][] }) { return <dl className="grid gap-3 sm:grid-cols-2">{items.map(([label, value]) => <div key={label} className="rounded-xl border border-amber-400/15 bg-slate-950/35 p-3"><dt className="text-xs uppercase tracking-wide text-amber-200/70">{label}</dt><dd className="mt-2 text-sm leading-5 text-slate-200">{value}</dd></div>)}</dl>; }
function GraphNode({ detail, onSelect, selected }: { detail: GraphDetail; onSelect: (detail: GraphDetail) => void; selected: boolean }) { return <button type="button" onClick={() => onSelect(detail)} className={`w-full rounded-lg border p-3 text-left transition ${selected ? 'border-violet-300 bg-violet-400/15 ring-1 ring-violet-300/30' : 'border-slate-700 bg-slate-900 hover:border-violet-400/50'}`}><p className="text-[10px] uppercase tracking-wide text-slate-500">{detail.relationship}</p><p className="mt-1 font-mono text-xs text-violet-100">{abbreviate(detail.address)}</p><p className="mt-1 text-xs text-slate-400">{detail.transactionCount} observed transfer{detail.transactionCount === 1 ? '' : 's'}</p></button>; }
function GraphDetailPanel({ detail }: { detail: GraphDetail | null }) { if (!detail) return <div className="rounded-xl border border-dashed border-slate-700 bg-slate-950/35 p-5 text-sm text-slate-500">Select an observed wallet node to view its direct interaction evidence.</div>; return <aside className="rounded-xl border border-slate-800 bg-slate-950/55 p-5"><p className="text-xs font-medium uppercase tracking-wide text-cyan-300">Selected node evidence</p><div className="mt-3"><WalletAddress address={detail.address} /></div><dl className="mt-4 space-y-3 text-sm"><DetailRow label="Relationship" value={detail.relationship} /><DetailRow label="Transaction count" value={String(detail.transactionCount)} /><DetailRow label="Observed amount" value={formatEth(detail.observedWei)} /><DetailRow label="First interaction" value={formatTimestamp(detail.firstInteraction)} /><DetailRow label="Last interaction" value={formatTimestamp(detail.lastInteraction)} /></dl><p className="mt-4 text-xs leading-5 text-slate-500">This is a direct on-chain relationship only. It does not verify address ownership or service identity.</p></aside>; }
function DetailRow({ label, value }: { label: string; value: string }) { return <div className="flex items-start justify-between gap-4"><dt className="text-slate-500">{label}</dt><dd className="max-w-[60%] text-right font-mono text-xs text-slate-200">{value}</dd></div>; }
function AddressCell({ address, copied, onCopy }: { address: string | null; copied: string; onCopy: (value: string) => Promise<void> }) { if (!address) return <td className="px-4 py-3 text-slate-500">Contract creation</td>; return <td className="px-4 py-3"><div className="flex items-center gap-2"><a href={`https://etherscan.io/address/${address}`} target="_blank" rel="noreferrer" className="font-mono text-slate-200 hover:text-cyan-200" title={address}>{abbreviate(address)}</a><button type="button" onClick={() => void onCopy(address)} aria-label={`Copy address ${address}`} className="text-slate-500 hover:text-cyan-200">{copied === address ? <CheckCircle2 size={14} className="text-emerald-300" /> : <Copy size={14} />}</button></div></td>; }
function StatusPill({ status }: { status: WalletTransaction['status'] }) { const style = status === 'success' ? 'border-emerald-400/25 bg-emerald-400/10 text-emerald-200' : status === 'failed' ? 'border-red-400/25 bg-red-400/10 text-red-200' : 'border-slate-700 bg-slate-800 text-slate-300'; return <span className={`rounded-full border px-2 py-1 text-xs font-medium capitalize ${style}`}>{status}</span>; }
function DirectionPill({ direction }: { direction: TransactionDirection }) { const style = direction === 'incoming' ? 'text-emerald-200' : direction === 'outgoing' ? 'text-violet-200' : 'text-slate-300'; const icon = direction === 'incoming' ? <ArrowDownLeft size={14} /> : direction === 'outgoing' ? <ArrowUpRight size={14} /> : <Activity size={14} />; return <span className={`inline-flex items-center gap-1.5 ${style}`}>{icon}{directionLabel(direction)}</span>; }
function LoadingWorkspace() { return <div className="scanning-surface grid gap-6 rounded-2xl p-1 lg:grid-cols-2" role="status" aria-busy="true" aria-label="Retrieving verified blockchain data"><div className="h-72 animate-pulse rounded-2xl border border-cyan-400/15 bg-slate-900/50" /><div className="h-72 animate-pulse rounded-2xl border border-cyan-400/15 bg-slate-900/50" /><div className="h-64 animate-pulse rounded-2xl border border-cyan-400/15 bg-slate-900/50 lg:col-span-2" /></div>; }
function EmptyWorkspace() { return <section className="rounded-2xl border border-dashed border-slate-700 bg-slate-900/30 p-10 text-center"><Network size={28} className="mx-auto text-cyan-300" /><h2 className="mt-4 text-lg font-medium text-white">Ready for an evidence-backed investigation</h2><p className="mx-auto mt-2 max-w-xl text-sm leading-6 text-slate-400">Enter an Ethereum wallet address to retrieve its current balance, transaction count, and recent normal transfer activity from the configured data source.</p></section>; }
function NoData({ message }: { message: string }) { return <div className="mt-5 rounded-xl border border-dashed border-slate-700 bg-slate-950/35 p-6 text-center text-sm text-slate-500">{message}</div>; }
